use std::collections::BTreeMap;
use std::io::{self, Read};

fn main() {
    let mut s = String::new();
    io::stdin().read_to_string(&mut s).unwrap();
    let mut m: BTreeMap<String, i128> = BTreeMap::new();
    let mut out = String::new();
    for line in s.lines() {
        let t: Vec<&str> = line.split_whitespace().collect();
        if t.is_empty() {
            continue;
        }
        let amt = |i: usize| -> Option<i128> { t.get(i).and_then(|x| x.parse::<i128>().ok()) };
        let unk = |n: &str| format!("error: unknown account {}\n", n);
        match t[0] {
            "open" if t.len() >= 3 => {
                match amt(2) {
                    Some(a) if a >= 0 => {
                        if m.contains_key(t[1]) {
                            out += "error: duplicate account\n";
                        } else {
                            m.insert(t[1].to_string(), a);
                            out += "ok\n";
                        }
                    }
                    _ => out += "error: invalid amount\n",
                }
            }
            "deposit" | "withdraw" if t.len() >= 3 => {
                match amt(2) {
                    Some(a) if a > 0 => {
                        if let Some(b) = m.get_mut(t[1]) {
                            if t[0] == "deposit" {
                                *b += a;
                                out += "ok\n";
                            } else if *b < a {
                                out += "error: insufficient funds\n";
                            } else {
                                *b -= a;
                                out += "ok\n";
                            }
                        } else {
                            out += &unk(t[1]);
                        }
                    }
                    _ => out += "error: invalid amount\n",
                }
            }
            "transfer" if t.len() >= 4 => {
                match amt(3) {
                    Some(a) if a > 0 => {
                        if !m.contains_key(t[1]) {
                            out += &unk(t[1]);
                        } else if !m.contains_key(t[2]) {
                            out += &unk(t[2]);
                        } else if t[1] == t[2] {
                            out += "error: same account\n";
                        } else if m[t[1]] < a {
                            out += "error: insufficient funds\n";
                        } else {
                            *m.get_mut(t[1]).unwrap() -= a;
                            *m.get_mut(t[2]).unwrap() += a;
                            out += "ok\n";
                        }
                    }
                    _ => out += "error: invalid amount\n",
                }
            }
            "balance" if t.len() >= 2 => match m.get(t[1]) {
                Some(b) => out += &format!("{}\n", b),
                None => out += &unk(t[1]),
            },
            _ => {}
        }
    }
    for (k, v) in &m {
        out += &format!("{} {}\n", k, v);
    }
    print!("{}", out);
}

